    "summary": "Вы состояли в Белых Соколах и работали в шпионской сети, которая борется против Нарекателей и Белой Веры.",
    "action": "Когда в свой ход вы успешно скрываетесь действием, можете потратить применение этой черты без отдельного действия. До конца этого хода первые 10 футов вашего перемещения не требуют дополнительной траты за немагическую труднопроходимую местность. В этот же ход вы можете открыть или закрыть одну незапертую дверь в пределах досягаемости без отдельного взаимодействия с предметом. Это не даёт дополнительного перемещения, не отменяет шум и не сохраняет скрытность там, где обычные правила её прекращают. При скорости 0 двигаться нельзя.",
    "conditions": "Триггер, действие, цели и ограничения указаны в эффектах.",
    "uses": "Число применений равно вашему бонусу мастерства. Все применения восстанавливаются, когда вы заканчиваете продолжительный отдых.",
    "recovery": "Применения восстанавливаются по окончании продолжительного отдыха; постоянные свойства не требуют восстановления.",
    "benefits": [
      {
        "title": "Уйти из-под взгляда",
        "text": "Когда в свой ход вы успешно скрываетесь действием, можете потратить применение этой черты без отдельного действия. До конца этого хода первые 10 футов вашего перемещения не требуют дополнительной траты за немагическую труднопроходимую местность. В этот же ход вы можете открыть или закрыть одну незапертую дверь в пределах досягаемости без отдельного взаимодействия с предметом. Это не даёт дополнительного перемещения, не отменяет шум и не сохраняет скрытность там, где обычные правила её прекращают. При скорости 0 двигаться нельзя."
      },
      {
        "title": "Опыт прошлого",
        "text": "После минуты наблюдения за обычной одеждой вы точно помните её видимые приметы до следующего продолжительного отдыха. Смена одежды или облика может сделать эти приметы бесполезными."
      },
      {
        "title": "Использование и восстановление",
        "text": "Число применений равно вашему бонусу мастерства. Все применения восстанавливаются, когда вы заканчиваете продолжительный отдых. Если приём готовит эффект на будущее, применение тратится при подготовке, кроме прямо указанного в правиле другого момента. Все ваши незавершённые подготовки этой черты заканчиваются при завершении вами продолжительного отдыха до восстановления применений. Подготовки одной и той же черты от нескольких персонажей заменяют друг друга, если в основном правиле не установлено более строгое ограничение. Материалы и инструменты, названные в правиле, нужно иметь; черта не создаёт их бесплатно."
      },
      {
        "title": "Условия",
        "text": "Одна версия этой черты может быть выбрана только один раз. Используйте версию своей редакции; версии одной черты не складываются. Одно событие допускает не более одного применения этой черты. Повторный бросок нельзя снова перебросить этой же чертой. Состояние недееспособности запрещает использование активного приёма. Постоянные свойства действуют без расхода применений."
      }
    ],
