      "**Ещё одну сказку.** Потратив 10 минут на песню или рассказ во время короткого отдыха, выберите до трёх согласных слушателей, понимающих вас. До своего следующего продолжительного отдыха каждый может один раз реакцией после провала спасброска против испуга повторить этот спасбросок и использовать новый результат. Повторный рассказ заменяет прежний эффект этой черты независимо от исполнителя. Для песни можно использовать имеющийся музыкальный инструмент; он не обязателен. Это не снимает испуг без успешного спасброска.",
