      "**Использование и восстановление.** Одно применение. Все применения восстанавливаются, когда вы заканчиваете продолжительный отдых. Если приём готовит эффект на будущее, применение тратится при подготовке, кроме прямо указанного в правиле другого момента. Все ваши незавершённые подготовки этой черты заканчиваются при завершении вами продолжительного отдыха до восстановления применений. Подготовки одной и той же черты от нескольких персонажей заменяют друг друга, если в основном правиле не установлено более строгое ограничение. Материалы и инструменты, названные в правиле, нужно иметь; черта не создаёт их бесплатно.",
