      "**Руки помнят.** Действием возьмите имеющийся ремесленный инструмент и выберите его на ближайший час. Если вы не владеете им, вы получаете владение на этот срок. Если владеете, один раз в течение этого часа после броска, но до объявления результата можете без действия прибавить 1к4 к проверке характеристики с этим инструментом. Выбранную характеристику и Сл определяет обычная задача. Новое применение заканчивает предыдущее; оно не ускоряет работу и не даёт Компетентность.",
