    "intro": "Вы учились в цехе мастеров, почитавших Гендина, Великого Строителя.\n\nОтдельная опциональная Feat 2014, приобретаемая вместо повышения характеристик либо через явно разрешённый источник черты. Предыстория 2014 не выдаёт её автоматически. Повышение +1 — свойство этой авторской черты, не предыстории.",
    "benefits": [
      "**Закалка опыта.** Увеличьте на 1 значение одной из следующих характеристик: Сила, Интеллект. Максимум — 20.",
      "**Не скрывать трещину.** Когда вы проваливаете проверку Силы или Ловкости с ремесленным инструментом для ремонта немагического предмета, потратьте ещё 10 минут и повторите проверку с Преимуществом, используя новый результат. После повтора эту конкретную поломку нельзя снова исправлять этой чертой до продолжительного отдыха. Если проверка успешна, до вашего следующего продолжительного отдыха вы можете один раз без действия прибавить 1к4 к проверке характеристики, использующей этот предмет по его обычному назначению, объявив это до броска. Это не действует на атаки, спасброски, цену, КД или урон предмета и не возвращает потраченные материалы.",
      "**Опыт прошлого.** После минуты осмотра предмета, который вы лично ремонтировали, вы узнаёте свои видимые следы работы. Это не обнаруживает скрытый дефект, проклятие или чужую подделку без проверки.",
      "**Использование и восстановление.** Два применения. Все применения восстанавливаются, когда вы заканчиваете продолжительный отдых. Если приём готовит эффект на будущее, применение тратится при подготовке, кроме прямо указанного в правиле другого момента. Все ваши незавершённые подготовки этой черты заканчиваются при завершении вами продолжительного отдыха до восстановления применений. Подготовки одной и той же черты от нескольких персонажей заменяют друг друга, если в основном правиле не установлено более строгое ограничение. Материалы и инструменты, названные в правиле, нужно иметь; черта не создаёт их бесплатно.",
      "**Условия.** Одна версия этой черты может быть выбрана только один раз. Используйте версию своей редакции; версии одной черты не складываются. Одно событие допускает не более одного применения этой черты. Повторный бросок нельзя снова перебросить этой же чертой. Состояние недееспособности запрещает использование активного приёма. Постоянные свойства действуют без расхода применений."
    ],
