      "**Опыт прошлого.** Вы изучаете заговор Починка; Интеллект, Мудрость или Харизма, выбранные при получении черты, служат его характеристикой. Заговор действует по обычным правилам, в том числе не возвращает магию предмету. Починка — заговор списка Волшебника; обычные время, компоненты и дистанция сохраняются. Ячейки не требуются; магия предмета не восстанавливается.",
      "**Использование и восстановление.** Два применения. Все применения восстанавливаются, когда вы заканчиваете продолжительный отдых. Если приём готовит эффект на будущее, применение тратится при подготовке, кроме прямо указанного в правиле другого момента. Все ваши незавершённые подготовки этой черты заканчиваются при завершении вами продолжительного отдыха до восстановления применений. Подготовки одной и той же черты от нескольких персонажей заменяют друг друга, если в основном правиле не установлено более строгое ограничение. Материалы и инструменты, названные в правиле, нужно иметь; черта не создаёт их бесплатно.",
      "**Условия.** Одна версия этой черты может быть выбрана только один раз. Используйте версию своей редакции; версии одной черты не складываются. Одно событие допускает не более одного применения этой черты. Повторный бросок нельзя снова перебросить этой же чертой. Состояние недееспособности запрещает использование активного приёма. Постоянные свойства действуют без расхода применений. Если свойство даёт заговор, используйте его текст из своей редакции: время, компоненты, дистанция, длительность и концентрация сохраняются. Черта не даёт ячеек и не позволяет заменять известный заговор, если это прямо не разрешено."
